(()=>{
 const previous=EmberViewport.prototype.render;
 EmberViewport.prototype.render=function(particles,settings,grid,light){
  const T=Ember3D;if(!this.ribbonMesh){const maximum=this.max*6;this.ribbonPositions=new Float32Array(maximum*3);this.ribbonColors=new Float32Array(maximum*4);const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(this.ribbonPositions,3).setUsage(T.DynamicDrawUsage));geometry.setAttribute('ribbonColor',new T.BufferAttribute(this.ribbonColors,4).setUsage(T.DynamicDrawUsage));const material=new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.DoubleSide,vertexShader:'attribute vec4 ribbonColor;varying vec4 shade;void main(){shade=ribbonColor;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec4 shade;void main(){gl_FragColor=shade;\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'});this.ribbonMesh=new T.Mesh(geometry,material);this.ribbonMesh.frustumCulled=false;this.scene.add(this.ribbonMesh);}
  const groups=new Map();for(const p of particles){const s=p.settings||settings;if(!s.trail||s.trailMode!=='ribbon')continue;if(!groups.has(s))groups.set(s,[]);groups.get(s).push(p);}let vertex=0;const color=new T.Color(),side=new T.Vector3(),tangent=new T.Vector3(),view=new T.Vector3();for(const [s,points]of groups){const edges=points.map((p,i)=>{const before=points[Math.max(0,i-1)],after=points[Math.min(points.length-1,i+1)];tangent.set(after.x-before.x,after.y-before.y,after.z-before.z);view.set(this.camera.position.x-p.x,this.camera.position.y-p.y,this.camera.position.z-p.z);side.crossVectors(tangent,view);if(side.lengthSq()<1e-12)side.set(1,0,0);side.normalize().multiplyScalar(EmberRibbons.width(s,p.age/p.life)*.5);color.set(EmberAnimation.particleColor(s,p.age/p.life));const brightness=s.glow?3:1;return {a:[p.x-side.x,p.y-side.y,p.z-side.z],b:[p.x+side.x,p.y+side.y,p.z+side.z],color:[color.r*brightness,color.g*brightness,color.b*brightness,EmberLifetime.opacity(s,p.age/p.life)*(s.opacity??1)]};});for(let i=1;i<edges.length&&vertex+6<=this.max*6;i++){const a=edges[i-1],b=edges[i];for(const [edge,point]of [[a,a.a],[a,a.b],[b,b.a],[a,a.b],[b,b.b],[b,b.a]]){this.ribbonPositions.set(point,vertex*3);this.ribbonColors.set(edge.color,vertex*4);vertex++;}}}
  this.ribbonMesh.geometry.setDrawRange(0,vertex);for(const a of Object.values(this.ribbonMesh.geometry.attributes))a.needsUpdate=true;this.ribbonMesh.visible=vertex>0;previous.call(this,particles,settings,grid,light);
 };
})();
